insert into wlr_email_modelos (tipo, nome, quando, publico, ordem, automatico, textos) values
('aprovar-dispositivo','Aprovar dispositivo','Automático — quando alguém entra com o telefone de um membro num aparelho novo','automatico',10,true,'{"pt": {"assunto": "🔐 Aprove o seu acesso — Magnum Fest", "titulo": "{nome}, é você?", "corpo": "Recebemos um pedido para entrar no site da Magnum Fest com o seu WhatsApp, a partir de: **{aparelho}**.\n\nSe foi você, toque no botão abaixo. A tela onde você digitou o telefone entra sozinha, e este aparelho fica liberado daqui em diante.\n\nSe não foi você, ignore este e-mail: ninguém entra sem essa aprovação. O link vale por 30 minutos.", "botao": "APROVAR ESTE DISPOSITIVO"}, "es": {"assunto": "🔐 Aprueba tu acceso — Magnum Fest", "titulo": "{nome}, ¿eres tú?", "corpo": "Recibimos una solicitud para entrar al sitio de la Magnum Fest con tu WhatsApp, desde: **{aparelho}**.\n\nSi fuiste tú, toca el botón de abajo. La pantalla donde escribiste el teléfono entrará sola y este dispositivo quedará habilitado desde ahora.\n\nSi no fuiste tú, ignora este e-mail: nadie entra sin esta aprobación. El enlace vale por 30 minutos.", "botao": "APROBAR ESTE DISPOSITIVO"}, "en": {"assunto": "🔐 Approve your access — Magnum Fest", "titulo": "{nome}, is this you?", "corpo": "We received a request to sign in to the Magnum Fest site with your WhatsApp number, from: **{aparelho}**.\n\nIf it was you, tap the button below. The screen where you entered your number will sign in on its own, and this device will be approved from now on.\n\nIf it was not you, ignore this email: nobody gets in without this approval. The link is valid for 30 minutes.", "botao": "APPROVE THIS DEVICE"}}'::jsonb),
('boas-vindas','Boas-vindas','Automático — quando o confrade confirma presença','automatico',20,true,'{"pt": {"assunto": "🍷 Presença confirmada — Magnum Fest Licínio Dias 2026", "titulo": "Presença confirmada, {nome}!", "corpo": "Anote: **{data}, {hora}**, no **{local}**.\n\nÉ uma Magnum Fest: cada confrade leva **uma Magnum (1,5 L)**. Não há rateio antecipado — o restaurante cobra de cada um no dia.\n\nCada vinho passa pelos critérios da MFLD: nota mínima de 95 pontos (Robert Parker, Wine Spectator ou James Suckling) ou preço de € 400 ou mais, entre outras regras. Registre a sua Magnum no painel — o sistema confere os critérios na hora.", "botao": "ABRIR MEU PAINEL"}, "es": {"assunto": "🍷 Asistencia confirmada — Magnum Fest Licínio Dias 2026", "titulo": "¡Asistencia confirmada, {nome}!", "corpo": "Anota: **{data}, {hora}**, en **{local}**.\n\nEs una Magnum Fest: cada cofrade lleva **una Magnum (1,5 L)**. No hay pago por adelantado: el restaurante cobra a cada uno ese día.\n\nCada vino pasa por los criterios de la MFLD: puntuación mínima de 95 puntos (Robert Parker, Wine Spectator o James Suckling) o precio de 400 € o más, entre otras reglas. Registra tu Magnum en tu panel: el sistema verifica los criterios al instante.", "botao": "ABRIR MI PANEL"}, "en": {"assunto": "🍷 You''re in — Magnum Fest Licínio Dias 2026", "titulo": "You''re in, {nome}!", "corpo": "Save the date: **{data}, {hora}**, at **{local}**.\n\nIt is a Magnum Fest: every member brings **one Magnum (1.5 L)**. There is no advance payment — the restaurant charges each person on the day.\n\nEvery wine must meet the MFLD criteria: a minimum score of 95 points (Robert Parker, Wine Spectator or James Suckling) or a price of €400 or more, among other rules. Register your Magnum in your panel — the system checks the criteria on the spot.", "botao": "OPEN MY PANEL"}}'::jsonb),
('garrafa-registrada','Magnum registrada','Automático — quando o confrade registra um vinho','automatico',30,true,'{"pt": {"assunto": "🍷 {vinho} registrado — conferindo os critérios", "titulo": "Recebemos a sua Magnum, {nome}", "corpo": "**{vinho}**\n\nEstamos conferindo as notas de crítica, o preço e as demais regras da MFLD. Em alguns minutos o parecer aparece no seu painel e chega por e-mail.", "botao": "VER NO MEU PAINEL"}, "es": {"assunto": "🍷 {vinho} registrado — verificando los criterios", "titulo": "Recibimos tu Magnum, {nome}", "corpo": "**{vinho}**\n\nEstamos verificando las puntuaciones de la crítica, el precio y las demás reglas de la MFLD. En unos minutos el dictamen aparecerá en tu panel y te llegará por e-mail.", "botao": "VER EN MI PANEL"}, "en": {"assunto": "🍷 {vinho} registered — checking the criteria", "titulo": "We have your Magnum, {nome}", "corpo": "**{vinho}**\n\nWe are checking the critic scores, the price and the other MFLD rules. In a few minutes the verdict will appear in your panel and arrive by email.", "botao": "SEE IN MY PANEL"}}'::jsonb),
('parecer','Parecer dos critérios','Automático — quando a análise do vinho termina','automatico',40,true,'{"pt": {"assunto": "{situacao} · {vinho} — parecer da MFLD", "titulo": "{nome}, o parecer da sua Magnum", "corpo": "**{vinho}**\n\n**{situacao}**\n\n{resumo}\n\n{{criterios}}\n\n{proximo_passo}", "botao": "ABRIR MEU PAINEL"}, "es": {"assunto": "{situacao} · {vinho} — dictamen de la MFLD", "titulo": "{nome}, el dictamen de tu Magnum", "corpo": "**{vinho}**\n\n**{situacao}**\n\n{resumo}\n\n{{criterios}}\n\n{proximo_passo}", "botao": "ABRIR MI PANEL"}, "en": {"assunto": "{situacao} · {vinho} — MFLD verdict", "titulo": "{nome}, the verdict on your Magnum", "corpo": "**{vinho}**\n\n**{situacao}**\n\n{resumo}\n\n{{criterios}}\n\n{proximo_passo}", "botao": "OPEN MY PANEL"}}'::jsonb),
('decisao-conselho','Decisão do conselho','Automático — quando o conselho aprova ou recusa um vinho','automatico',50,true,'{"pt": {"assunto": "{situacao} · {vinho} — decisão do conselho", "titulo": "{nome}, o conselho decidiu", "corpo": "O conselho da Wine Lovers Recife **{decisao}** o **{vinho}** para a Magnum Fest.\n\n{motivo}\n\n{proximo_passo}", "botao": "ABRIR MEU PAINEL"}, "es": {"assunto": "{situacao} · {vinho} — decisión del consejo", "titulo": "{nome}, el consejo decidió", "corpo": "El consejo de Wine Lovers Recife **{decisao}** el **{vinho}** para la Magnum Fest.\n\n{motivo}\n\n{proximo_passo}", "botao": "ABRIR MI PANEL"}, "en": {"assunto": "{situacao} · {vinho} — board decision", "titulo": "{nome}, the board has decided", "corpo": "The Wine Lovers Recife board **{decisao}** **{vinho}** for the Magnum Fest.\n\n{motivo}\n\n{proximo_passo}", "botao": "OPEN MY PANEL"}}'::jsonb),
('conselho-avaliar','Aviso ao conselho','Automático — quando um vinho precisa do conselho','conselho',60,true,'{"pt": {"assunto": "🛡️ Conselho: avaliar {vinho} ({confrade})", "titulo": "{nome}, um vinho aguarda o conselho", "corpo": "**{confrade}** registrou **{vinho}**.\n\n{resumo}\n\n{{criterios}}\n\nAprove ou recuse no painel do conselho — a decisão fica registrada com o seu nome e o confrade é avisado.", "botao": "ABRIR O PAINEL DO CONSELHO"}, "es": {"assunto": "🛡️ Consejo: evaluar {vinho} ({confrade})", "titulo": "{nome}, un vino espera al consejo", "corpo": "**{confrade}** registró **{vinho}**.\n\n{resumo}\n\n{{criterios}}\n\nAprueba o rechaza en el panel del consejo.", "botao": "ABRIR EL PANEL DEL CONSEJO"}, "en": {"assunto": "🛡️ Board: review {vinho} ({confrade})", "titulo": "{nome}, a wine is waiting for the board", "corpo": "**{confrade}** registered **{vinho}**.\n\n{resumo}\n\n{{criterios}}\n\nApprove or decline it in the board panel.", "botao": "OPEN THE BOARD PANEL"}}'::jsonb),
('resumo','Resumo da carta','A cada 15 dias, às segundas, 10h','confirmados',70,false,'{"pt": {"assunto": "🍷 A carta da Magnum Fest — faltam {dias} dias", "titulo": "{nome}, a mesa está crescendo", "corpo": "Já são **{n_confirmados} confrades** confirmados e **{n_magnums} Magnums** aprovadas.\n\n{{novidades}}\n\n{{carta}}", "botao": "VER A CARTA COMPLETA"}, "es": {"assunto": "🍷 La carta de la Magnum Fest — faltan {dias} días", "titulo": "{nome}, la mesa sigue creciendo", "corpo": "Ya son **{n_confirmados} cofrades** confirmados y **{n_magnums} Magnums** aprobadas.\n\n{{novidades}}\n\n{{carta}}", "botao": "VER LA CARTA COMPLETA"}, "en": {"assunto": "🍷 The Magnum Fest wine list — {dias} days to go", "titulo": "{nome}, the table keeps growing", "corpo": "**{n_confirmados} members** have confirmed and **{n_magnums} Magnums** are approved.\n\n{{novidades}}\n\n{{carta}}", "botao": "SEE THE FULL LIST"}}'::jsonb),
('pauta-conselho','Pauta do conselho','Toda segunda, 9h','conselho',80,false,'{"pt": {"assunto": "🛡️ Pauta do conselho — Magnum Fest", "titulo": "{nome}, a pauta da semana", "corpo": "{{pauta}}\n\nAs decisões são tomadas no painel do conselho, com o seu link pessoal.", "botao": "ABRIR O PAINEL DO CONSELHO"}, "es": {"assunto": "🛡️ Agenda del consejo — Magnum Fest", "titulo": "{nome}, la agenda de la semana", "corpo": "{{pauta}}", "botao": "ABRIR EL PANEL DEL CONSEJO"}, "en": {"assunto": "🛡️ Board agenda — Magnum Fest", "titulo": "{nome}, this week''s agenda", "corpo": "{{pauta}}", "botao": "OPEN THE BOARD PANEL"}}'::jsonb),
('falta-magnum','Falta a sua Magnum','30/10 e 20/11, 10h — só para quem não tem Magnum aprovada','sem_magnum',90,false,'{"pt": {"assunto": "🍾 Falta a sua Magnum — Magnum Fest", "titulo": "{nome}, falta a sua Magnum", "corpo": "A sua presença está confirmada, mas ainda não há uma Magnum aprovada no seu nome.\n\nRegistre o vinho no painel — o sistema confere na hora a nota (95+ em Parker, Wine Spectator ou Suckling) ou o preço (€ 400 ou mais), a safra e a região.\n\n{{minhas_garrafas}}", "botao": "REGISTRAR A MINHA MAGNUM"}, "es": {"assunto": "🍾 Falta tu Magnum — Magnum Fest", "titulo": "{nome}, falta tu Magnum", "corpo": "Tu asistencia está confirmada, pero todavía no hay una Magnum aprobada a tu nombre.\n\nRegistra el vino en tu panel: el sistema verifica al instante la puntuación (95+ en Parker, Wine Spectator o Suckling) o el precio (400 € o más), la añada y la región.\n\n{{minhas_garrafas}}", "botao": "REGISTRAR MI MAGNUM"}, "en": {"assunto": "🍾 Your Magnum is missing — Magnum Fest", "titulo": "{nome}, your Magnum is missing", "corpo": "You are confirmed, but there is no approved Magnum in your name yet.\n\nRegister your wine in your panel — the system checks the score (95+ from Parker, Wine Spectator or Suckling) or the price (€400 or more), the vintage and the region on the spot.\n\n{{minhas_garrafas}}", "botao": "REGISTER MY MAGNUM"}}'::jsonb),
('lembrete-1-mes','Falta 1 mês','11/11, 10h','confirmados',100,false,'{"pt": {"assunto": "📅 Falta 1 mês — Magnum Fest Licínio Dias", "titulo": "{nome}, falta um mês", "corpo": "**{data}, {hora}** — {local}.\n\n{{minhas_garrafas}}\n\n**Valor por pessoa, pago no dia:** {valor}\n\n{{cardapio}}", "botao": "ABRIR MEU PAINEL"}, "es": {"assunto": "📅 Falta 1 mes — Magnum Fest Licínio Dias", "titulo": "{nome}, falta un mes", "corpo": "**{data}, {hora}** — {local}.\n\n{{minhas_garrafas}}\n\n**Precio por persona, se paga ese día:** {valor}\n\n{{cardapio}}", "botao": "ABRIR MI PANEL"}, "en": {"assunto": "📅 One month to go — Magnum Fest Licínio Dias", "titulo": "{nome}, one month to go", "corpo": "**{data}, {hora}** — {local}.\n\n{{minhas_garrafas}}\n\n**Price per person, paid on the day:** {valor}\n\n{{cardapio}}", "botao": "OPEN MY PANEL"}}'::jsonb),
('carta-fechada','A carta da festa','1/12, 10h','confirmados',110,false,'{"pt": {"assunto": "🍷 A carta da Magnum Fest Licínio Dias 2026", "titulo": "{nome}, esta é a carta da festa", "corpo": "**{n_magnums} Magnums** aprovadas para {data}.\n\n{{carta}}", "botao": "VER A CARTA NO SITE"}, "es": {"assunto": "🍷 La carta de la Magnum Fest Licínio Dias 2026", "titulo": "{nome}, esta es la carta de la fiesta", "corpo": "**{n_magnums} Magnums** aprobadas para el {data}.\n\n{{carta}}", "botao": "VER LA CARTA EN EL SITIO"}, "en": {"assunto": "🍷 The Magnum Fest Licínio Dias 2026 wine list", "titulo": "{nome}, here is the party''s list", "corpo": "**{n_magnums} Magnums** approved for {data}.\n\n{{carta}}", "botao": "SEE THE LIST ONLINE"}}'::jsonb),
('lembrete-1-semana','Falta 1 semana','4/12, 10h','confirmados',120,false,'{"pt": {"assunto": "📅 Falta 1 semana — Magnum Fest Licínio Dias", "titulo": "{nome}, falta só uma semana", "corpo": "**{data}, {hora}** — {local}.\n\n{{minhas_garrafas}}\n\n**Valor por pessoa, pago no dia:** {valor}\n\n{{cardapio}}", "botao": "ABRIR MEU PAINEL"}, "es": {"assunto": "📅 Falta 1 semana — Magnum Fest Licínio Dias", "titulo": "{nome}, falta solo una semana", "corpo": "**{data}, {hora}** — {local}.\n\n{{minhas_garrafas}}\n\n**Precio por persona, se paga ese día:** {valor}\n\n{{cardapio}}", "botao": "ABRIR MI PANEL"}, "en": {"assunto": "📅 One week to go — Magnum Fest Licínio Dias", "titulo": "{nome}, just one week to go", "corpo": "**{data}, {hora}** — {local}.\n\n{{minhas_garrafas}}\n\n**Price per person, paid on the day:** {valor}\n\n{{cardapio}}", "botao": "OPEN MY PANEL"}}'::jsonb),
('lembrete-hoje','É hoje','11/12, 8h','confirmados',130,false,'{"pt": {"assunto": "🍷 É HOJE — Magnum Fest Licínio Dias, {hora}", "titulo": "{nome}, é hoje! 🥂", "corpo": "**{hora}** — {local}. Não esqueça a sua Magnum!\n\n{{minhas_garrafas}}\n\n**Valor por pessoa, pago no restaurante:** {valor}\n\n**A votação:** durante a festa, aponte a câmera do celular para o QR Code das mesas e vote nos melhores vinhos — um voto por categoria.", "botao": "ABRIR MEU PAINEL"}, "es": {"assunto": "🍷 ES HOY — Magnum Fest Licínio Dias, {hora}", "titulo": "¡{nome}, es hoy! 🥂", "corpo": "**{hora}** — {local}. ¡No olvides tu Magnum!\n\n{{minhas_garrafas}}\n\n**Precio por persona, se paga en el restaurante:** {valor}\n\n**La votación:** durante la fiesta, apunta la cámara del móvil al código QR de las mesas y vota por los mejores vinos, un voto por categoría.", "botao": "ABRIR MI PANEL"}, "en": {"assunto": "🍷 IT''S TODAY — Magnum Fest Licínio Dias, {hora}", "titulo": "{nome}, it''s today! 🥂", "corpo": "**{hora}** — {local}. Don''t forget your Magnum!\n\n{{minhas_garrafas}}\n\n**Price per person, paid at the restaurant:** {valor}\n\n**Voting:** during the party, point your phone''s camera at the QR code on the tables and vote for the best wines — one vote per category.", "botao": "OPEN MY PANEL"}}'::jsonb),
('votacao-aberta','Urna aberta','Automático — quando o conselho abre a urna','automatico',140,true,'{"pt": {"assunto": "🗳️ A urna está aberta — vote nos melhores vinhos", "titulo": "{nome}, a votação começou!", "corpo": "Um voto por categoria — Melhor Vinho, Melhor Tinto, Melhor Branco e Melhor Espumante. Você pode mudar de ideia enquanto a urna estiver aberta.", "botao": "VOTAR AGORA"}, "es": {"assunto": "🗳️ La urna está abierta — vota por los mejores vinos", "titulo": "¡{nome}, empezó la votación!", "corpo": "Un voto por categoría: Mejor Vino, Mejor Tinto, Mejor Blanco y Mejor Espumoso. Puedes cambiar de opinión mientras la urna esté abierta.", "botao": "VOTAR AHORA"}, "en": {"assunto": "🗳️ Voting is open — pick the best wines", "titulo": "{nome}, voting has started!", "corpo": "One vote per category — Best Wine, Best Red, Best White and Best Sparkling. You can change your mind while voting is open.", "botao": "VOTE NOW"}}'::jsonb),
('resultados','Resultados','Automático — quando o conselho publica os resultados','automatico',150,true,'{"pt": {"assunto": "🏆 Os melhores vinhos da Magnum Fest", "titulo": "{nome}, temos vencedores!", "corpo": "{{podio}}", "botao": "VER NO SITE"}, "es": {"assunto": "🏆 Los mejores vinos de la Magnum Fest", "titulo": "¡{nome}, tenemos ganadores!", "corpo": "{{podio}}", "botao": "VER EN EL SITIO"}, "en": {"assunto": "🏆 The best wines of the Magnum Fest", "titulo": "{nome}, we have winners!", "corpo": "{{podio}}", "botao": "SEE ONLINE"}}'::jsonb),
('agradecimento','Obrigado','12/12, 10h','confirmados',160,false,'{"pt": {"assunto": "🥂 Obrigado — Magnum Fest Licínio Dias 2026", "titulo": "{nome}, obrigado pela festa", "corpo": "Foram **{n_magnums} Magnums** e **{n_confirmados} confrades** à mesa, em homenagem a Licínio Dias.\n\n{{podio}}\n\nAté a próxima Magnum Fest.", "botao": "VER O PÓDIO"}, "es": {"assunto": "🥂 Gracias — Magnum Fest Licínio Dias 2026", "titulo": "{nome}, gracias por la fiesta", "corpo": "Fueron **{n_magnums} Magnums** y **{n_confirmados} cofrades** en la mesa, en homenaje a Licínio Dias.\n\n{{podio}}\n\nHasta la próxima Magnum Fest.", "botao": "VER EL PODIO"}, "en": {"assunto": "🥂 Thank you — Magnum Fest Licínio Dias 2026", "titulo": "{nome}, thank you for a wonderful day", "corpo": "**{n_magnums} Magnums** and **{n_confirmados} members** at the table, in honour of Licínio Dias.\n\n{{podio}}\n\nSee you at the next Magnum Fest.", "botao": "SEE THE PODIUM"}}'::jsonb),
('comunicado','Comunicado livre','Só manual — escreva e envie quando quiser','confirmados',170,false,'{"pt": {"assunto": "Magnum Fest Licínio Dias 2026", "titulo": "{nome},", "corpo": "Escreva aqui o recado.", "botao": "ABRIR MEU PAINEL"}, "es": {"assunto": "Magnum Fest Licínio Dias 2026", "titulo": "{nome}:", "corpo": "Escribe aquí el mensaje.", "botao": "ABRIR MI PANEL"}, "en": {"assunto": "Magnum Fest Licínio Dias 2026", "titulo": "{nome},", "corpo": "Write your message here.", "botao": "OPEN MY PANEL"}}'::jsonb)
